svg.script:
(function(){
  var z0=document.getElementById('lookZone'),svg=z0?z0.ownerSVGElement:null;
  if(!svg||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  var zone=svg.querySelector('#lookZone'),head=svg.querySelector('#headPtr'),face=svg.querySelector('#facePtr'),
      hair=svg.querySelector('#hairPtr'),pupil=svg.querySelector('#pupilPtr'),brow=svg.querySelector('#browPtr');
  var HX=769,HY=240;
  var pIdle=svg.querySelector('.pupilIdle'),idle={x:0,y:0},held=[],typing=[];
  var cur={x:0,y:0},tgt={x:0,y:0},eye={x:0,y:0},eyeT={x:0,y:0},active=false,raf=0,near=false;
  function clamp(v){return Math.max(-1,Math.min(1,v));}
  function toSvg(e){var p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
  function set(el,t){el.setAttribute('transform',t);}
  function frame(){
    cur.x+=(tgt.x-cur.x)*.14;cur.y+=(tgt.y-cur.y)*.14;eye.x+=(eyeT.x-eye.x)*.22;eye.y+=(eyeT.y-eye.y)*.22;
    var x=cur.x,y=cur.y;
    set(head,'rotate('+(x*9).toFixed(2)+' 131 200) translate('+(x*2).toFixed(2)+' '+(y*2).toFixed(2)+')');
    set(face,'translate('+(x*5.5).toFixed(2)+' '+(y*(0>y?3:4.5)).toFixed(2)+')');
    set(hair,'translate('+(x*2.5).toFixed(2)+' '+(y*(0>y?3:4.5)).toFixed(2)+') translate(131 170) skewX('+(Math.atan(x*6/26)*57.3).toFixed(2)+') scale(1 '+(1+y*(0>y?.25:.22)).toFixed(3)+') translate(-131 -170)');
    set(pupil,'translate('+(eye.x*2.1-idle.x).toFixed(2)+' '+(eye.y*2.1-idle.y).toFixed(2)+')');
    set(brow,'translate(0 '+(Math.min(0,y)*0.3).toFixed(2)+')');

    var moving=Math.abs(tgt.x-cur.x)+Math.abs(tgt.y-cur.y)+Math.abs(eyeT.x-eye.x)+Math.abs(eyeT.y-eye.y)>.002;
    if(active||moving){raf=requestAnimationFrame(frame);}
    else{raf=0;svg.classList.remove('tracking');held.forEach(function(a){a.play();});held=[];typing.forEach(function(a){a.play();});typing=[];[head,face,hair,pupil,brow].forEach(function(el){el.removeAttribute('transform');});}
  }
  function kick(){if(!raf)raf=requestAnimationFrame(frame);}
  zone.addEventListener('pointermove',function(e){
    var p=toSvg(e),dx=p.x-HX,dy=p.y-HY;
    tgt.x=clamp(dx/150);tgt.y=clamp(dy/(0>dy?60:160));
    var d=Math.max(Math.hypot(dx,dy),40);eyeT.x=dx/d;eyeT.y=dy/d;
    near=55>Math.hypot(dx,dy);
    if(!svg.classList.contains('tracking')){held=pIdle.getAnimations().filter(function(a){return a.playState==='running';});held.forEach(function(a){a.pause();});typing=[].concat.apply([],[].map.call(svg.querySelectorAll('.armL,.armR,.handL,.handR,.key'),function(el){return el.getAnimations();})).filter(function(a){return a.playState==='running';});typing.forEach(function(a){a.pause();a.currentTime=0;});   /* typing stops: hands rest on the keys, no sparks */var m=new DOMMatrix(getComputedStyle(pIdle).transform);idle.x=m.e;idle.y=m.f;eye.x=idle.x/2.1;eye.y=idle.y/2.1;}   // remember the reading step the eyes are on (reading pauses there)
    active=true;svg.classList.add('tracking');kick();
  });
  zone.addEventListener('pointerleave',function(){active=false;near=false;tgt.x=0;tgt.y=0;eyeT.x=idle.x/2.1;eyeT.y=idle.y/2.1;kick();});   // eyes glide back to the exact spot on the laptop line where reading paused, then reading carries on from that step
})();
